function render({width,state,params}) {
  const w = Math.max(320, Math.min(760, Number.isFinite(width) ? width : 560));
  const raw = params && Number.isFinite(params.shift) ? params.shift : 1;
  const shift = Math.max(0, Math.min(2, Math.round(raw)));
  const narrow = w < 560;
  const h = 242;
  const cell = narrow ? 26 : 34;
  const ink = '#292824', muted = '#77736b', blue = '#356d9b', orange = '#b96a27';
  const source = col => Array.from({length:2}, () => Array.from({length:5}, (_,j) => j === col ? 1 : 0));
  const pool = a => Array.from({length:4}, (_,j) => Math.max(a[0][j],a[0][j+1],a[1][j],a[1][j+1]));
  const inputs = [source(1),source(1+shift)];
  const outputs = inputs.map(pool);
  const changes = outputs[0].reduce((n,v,j) => n + (v !== outputs[1][j] ? 1 : 0), 0);
  let parts = [];
  const text = (x,y,s,size=14,anchor='middle',color=ink) => parts.push('<text x="'+x+'" y="'+y+'" font-size="'+size+'" text-anchor="'+anchor+'" fill="'+color+'">'+s+'</text>');
  const rect = (x,y,rw,rh,fill,stroke,sw=1) => parts.push('<rect x="'+x+'" y="'+y+'" width="'+rw+'" height="'+rh+'" fill="'+fill+'" stroke="'+stroke+'" stroke-width="'+sw+'"/>');
  const arrow = (x1,y1,x2,y2) => {
    parts.push('<path d="M '+x1+' '+y1+' L '+x2+' '+y2+'" fill="none" stroke="'+muted+'" stroke-width="1.4"/>');
    const vertical = x1 === x2;
    parts.push('<path d="'+(vertical ? 'M '+(x2-4)+' '+(y2-6)+' L '+x2+' '+y2+' L '+(x2+4)+' '+(y2-6) : 'M '+(x2-6)+' '+(y2-4)+' L '+x2+' '+y2+' L '+(x2-6)+' '+(y2+4))+'" fill="none" stroke="'+muted+'" stroke-width="1.4"/>');
  };
  const geometry = [];
  for (let k=0;k<2;k++) {
    let ix,iy,ox,oy;
    if (narrow) {
      const center = k === 0 ? w/4 : 3*w/4;
      ix = center-5*cell/2; iy=40;
      ox = center-4*cell/2; oy=144;
      text(center,24,k === 0 ? '原位 X' : '平移 +'+shift+' · X');
      arrow(center,101,center,123);
      text(center,138,'Y');
    } else {
      ix = (w-378)/2; iy = k === 0 ? 45 : 133;
      ox = ix+5*cell+72; oy = iy+cell/2;
      text(16,iy+cell+5,k === 0 ? '原位' : '平移 +'+shift,14,'start');
      arrow(ix+5*cell+14,iy+cell,ox-14,iy+cell);
    }
    for (let r=0;r<2;r++) for (let c=0;c<5;c++) {
      const active = c === 1 || c === 2;
      rect(ix+c*cell,iy+r*cell,cell,cell,active ? '#e8f0f5' : '#fffdf8','#d9d5cc');
      text(ix+(c+.5)*cell,iy+(r+.5)*cell+5,inputs[k][r][c],16);
    }
    rect(ix+cell,iy,2*cell,2*cell,'none',blue,2);
    for (let c=0;c<4;c++) {
      rect(ox+c*cell,oy,cell,cell,c === 1 ? '#f5e6d6' : '#fffdf8',c === 1 ? orange : '#d9d5cc',c === 1 ? 2 : 1);
      text(ox+(c+.5)*cell,oy+cell/2+5,outputs[k][c],16);
    }
    geometry.push({input:{x:ix,y:iy,rows:2,columns:5,cell},output:{x:ox,y:oy,rows:1,columns:4,cell},selectedWindow:{row:0,column:1,height:2,width:2},selectedOutput:[0,1]});
  }
  if (!narrow) {
    const ix=(w-378)/2;
    text(ix+5*cell/2,25,'X：2×5');
    text(ix+5*cell+72+2*cell,25,'Y：1×4');
  }
  text(w/2,222,'Y[0,1]：'+outputs[0][1]+' → '+outputs[1][1]+'　Δ单元：'+changes);
  const svg='<svg xmlns="http://www.w3.org/2000/svg" width="'+w+'" height="'+h+'" viewBox="0 0 '+w+' '+h+'" role="img"><title>局部稳定与整体变化</title><desc>手选二值响应，二维最大汇聚窗口为2乘2，步幅为1，无填充。蓝框对应输出下标0、1，橙色标出该输出。向右移动'+shift+'格后，该值由'+outputs[0][1]+'变为'+outputs[1][1]+'，完整输出有'+changes+'个单元改变。</desc><rect width="'+w+'" height="'+h+'" fill="#faf8f2"/><g font-family="sans-serif">'+parts.join('')+'</g></svg>';
  return {svg,facts:{state:'local',shift,inputShape:[2,5],inputResponseColumns:[1,1+shift],inputs,window:[2,2],stride:[1,1],padding:[0,0],outputs,outputShape:[1,4],selectedOutput:[0,1],selectedValues:[outputs[0][1],outputs[1][1]],changedOutputCount:changes,updateSteps:['将手选竖直响应从列1移动至列1+shift','逐列计算四个2×2窗口的最大值','比较固定输出与完整输出'],geometry,width:w,height:h}};
}

function render({width,state,params}) {
  const w=Math.max(320,Math.min(760,Number.isFinite(width)?width:560));
  const key=state==='padded'||state==='rectangular'?state:'default';
  const settings={default:{kernel:[3,3],stride:[3,3],padding:[0,0]},padded:{kernel:[3,3],stride:[2,2],padding:[1,1]},rectangular:{kernel:[2,3],stride:[2,3],padding:[0,1]}};
  const cfg=settings[key];
  const kh=cfg.kernel[0],kw=cfg.kernel[1],sh=cfg.stride[0],sw=cfg.stride[1],ph=cfg.padding[0],pw=cfg.padding[1];
  const input=Array.from({length:4},(_,r)=>Array.from({length:4},(_,c)=>4*r+c));
  const oh=Math.floor((4+2*ph-kh)/sh)+1,ow=Math.floor((4+2*pw-kw)/sw)+1;
  const rows=4+2*ph,cols=4+2*pw;
  const output=[],windows=[];
  for(let r=0;r<oh;r++) {
    const line=[];
    for(let c=0;c<ow;c++) {
      const origin=[r*sh-ph,c*sw-pw];
      const members=[];
      let maximum=-Infinity;
      for(let a=0;a<kh;a++) for(let b=0;b<kw;b++) {
        const ir=origin[0]+a,ic=origin[1]+b;
        const padded=ir<0||ir>=4||ic<0||ic>=4;
        const value=padded?-Infinity:input[ir][ic];
        maximum=Math.max(maximum,value);
        members.push({inputCoordinate:[ir,ic],padded,value:padded?'-Infinity':value});
      }
      line.push(maximum);
      windows.push({outputCoordinate:[r,c],inputOrigin:origin,members,maximum});
    }
    output.push(line);
  }
  const narrow=w<520;
  const cell=narrow?24:30,outCell=narrow?30:36;
  let ix,iy,ox,oy,h;
  if(narrow) {
    ix=(w-cols*cell)/2;iy=68;
    ox=(w-ow*outCell)/2;oy=iy+rows*cell+34;
    h=oy+oh*outCell+18;
  } else {
    const total=cols*cell+82+ow*outCell;
    ix=(w-total)/2;iy=54;
    ox=ix+cols*cell+82;oy=iy+(rows*cell-oh*outCell)/2;
    h=270;
  }
  const ink='#292824',muted='#77736b',blue='#356d9b',orange='#b96a27';
  let parts=[];
  const text=(x,y,s,size=14,anchor='middle',color=ink)=>parts.push('<text x="'+x+'" y="'+y+'" font-size="'+size+'" text-anchor="'+anchor+'" fill="'+color+'">'+s+'</text>');
  const rect=(x,y,rw,rh,fill,stroke,width=1,dash='')=>parts.push('<rect x="'+x+'" y="'+y+'" width="'+rw+'" height="'+rh+'" fill="'+fill+'" stroke="'+stroke+'" stroke-width="'+width+'"'+(dash?' stroke-dasharray="'+dash+'"':'')+'/>');
  const configLabel='窗口 '+kh+'×'+kw+'　步幅 '+sh+'×'+sw;
  text(w/2,22,narrow?configLabel:configLabel+'　填充 '+ph+'×'+pw);
  if(narrow) text(w/2,42,'填充 '+ph+'×'+pw);
  text(ix+cols*cell/2,iy-9,'X：4×4');
  for(let r=0;r<rows;r++) for(let c=0;c<cols;c++) {
    const ir=r-ph,ic=c-pw;
    const padded=ir<0||ir>=4||ic<0||ic>=4;
    const selected=r<kh&&c<kw;
    rect(ix+c*cell,iy+r*cell,cell,cell,selected?'#e8f0f5':padded?'#efede6':'#fffdf8','#d9d5cc');
    text(ix+(c+.5)*cell,iy+(r+.5)*cell+5,padded?'−∞':input[ir][ic],14,'middle',padded?muted:ink);
  }
  if(ph||pw) rect(ix+pw*cell,iy+ph*cell,4*cell,4*cell,'none','#969188',1,'3 3');
  rect(ix,iy,kw*cell,kh*cell,'none',blue,2);
  if(narrow) {
    const cy=iy+rows*cell;
    parts.push('<path d="M '+w/2+' '+(cy+7)+' L '+w/2+' '+(oy-8)+' M '+(w/2-4)+' '+(oy-14)+' L '+w/2+' '+(oy-8)+' L '+(w/2+4)+' '+(oy-14)+'" fill="none" stroke="'+muted+'" stroke-width="1.4"/>');
    text(16,oy+oh*outCell/2+5,'Y：'+oh+'×'+ow,14,'start');
  } else {
    const cy=iy+rows*cell/2;
    parts.push('<path d="M '+(ix+cols*cell+14)+' '+cy+' L '+(ox-14)+' '+cy+' M '+(ox-20)+' '+(cy-4)+' L '+(ox-14)+' '+cy+' L '+(ox-20)+' '+(cy+4)+'" fill="none" stroke="'+muted+'" stroke-width="1.4"/>');
    text(ox+ow*outCell/2,oy-10,'Y：'+oh+'×'+ow);
  }
  for(let r=0;r<oh;r++) for(let c=0;c<ow;c++) {
    const selected=r===0&&c===0;
    rect(ox+c*outCell,oy+r*outCell,outCell,outCell,selected?'#f5e6d6':'#fffdf8',selected?orange:'#d9d5cc',selected?2:1);
    text(ox+(c+.5)*outCell,oy+(r+.5)*outCell+5,output[r][c],16);
  }
  const svg='<svg xmlns="http://www.w3.org/2000/svg" width="'+w+'" height="'+h+'" viewBox="0 0 '+w+' '+h+'" role="img"><title>窗口、填充与输出形状</title><desc>输入为按行排列的0至15。最大汇聚窗口'+kh+'乘'+kw+'，步幅'+sh+'乘'+sw+'，填充'+ph+'乘'+pw+'，输出为'+oh+'乘'+ow+'。填充使用负无穷。蓝框为第一个窗口，橙色输出为'+output[0][0]+'。</desc><rect width="'+w+'" height="'+h+'" fill="#faf8f2"/><g font-family="sans-serif">'+parts.join('')+'</g></svg>';
  return {svg,facts:{state:key,input,inputShape:[1,1,4,4],kernel:cfg.kernel,stride:cfg.stride,padding:cfg.padding,paddingValue:'-Infinity',dilation:[1,1],ceilMode:false,paddedSpatialShape:[rows,cols],output,outputShape:[1,1,oh,ow],shapeCalculation:{height:{numerator:4+2*ph-kh,stride:sh,result:oh},width:{numerator:4+2*pw-kw,stride:sw,result:ow}},windows,selectedOutput:[0,0],updateSteps:['按参数在输入边界添加负无穷','按步幅列举完整窗口','计算每个窗口最大值并写入对应输出'],geometry:{input:{x:ix,y:iy,rows,columns:cols,cell},output:{x:ox,y:oy,rows:oh,columns:ow,cell:outCell}},width:w,height:h}};
}
